const { core } = require("photoshop");
let cancelled = false;
await core.executeAsModal(async (ctx) => {
  ctx.onCancel(() => { cancelled = true; });
  const h = await ctx.hostControl.suspendHistory({ documentID: require("photoshop").app.activeDocument.id, name: "Plugin batch" });
  try {
    for (let i = 0; i < 100 && !cancelled; i++) {
      ctx.reportProgress({ value: i / 100 });
      await step(i);
    }
  } finally { await ctx.hostControl.resumeHistory(h); }
}, { commandName: "Long job" });

