const { app, core, imaging, constants } = require("photoshop");
await core.executeAsModal(async () => {
  const doc = app.activeDocument;
  const w = 256, h = 256, buf = new Uint8Array(w * h * 4);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { const i = (y*w + x)*4; buf[i] = x; buf[i+1] = y; buf[i+2] = 128; buf[i+3] = 255; }
  const layer = await doc.createLayer(constants.LayerKind.NORMAL, { name: "gradient" });
  const img = await imaging.createImageDataFromBuffer(buf, { width: w, height: h, components: 4, colorSpace: "RGB", chunky: true });
  await imaging.putPixels({ documentID: doc.id, layerID: layer.id, imageData: img, replace: true, commandName: "Generate gradient" });
  img.dispose();
}, { commandName: "Put pixels demo" });

