const { app, core, imaging } = require("photoshop");
await core.executeAsModal(async () => {
  const doc = app.activeDocument, layer = doc.activeLayers[0];
  const w = doc.width, h = doc.height;
  const gray = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) gray[y*w + x] = x < w/2 ? 255 : 0;   // reveal left half
  const img = await imaging.createImageDataFromBuffer(gray, { width: w, height: h, components: 1, colorSpace: "Grayscale", chunky: true });
  await imaging.putLayerMask({ documentID: doc.id, layerID: layer.id, imageData: img, replace: true, commandName: "Half mask" });
  img.dispose();
}, { commandName: "Mask demo" });

const { app, imaging } = require("photoshop");
async function thumbnail(size = 200) {
  const res = await imaging.getPixels({ documentID: app.activeDocument.id, targetSize: { width: size }, componentSize: 8, colorSpace: "RGB", applyAlpha: true });
  const b64 = await imaging.encodeImageData({ imageData: res.imageData, base64: true });
  res.imageData.dispose();
  return "data:image/jpeg;base64," + b64;
}

